import fs from'node:fs';import{loadAnny,loadMHR,gunzip}from'../teachers.mjs';import{sourceWorld}from'./math.mjs';import{buildTargetBinding}from'./TargetBinding.mjs';const m=loadMHR(),a=loadAnny(),c=JSON.parse(new TextDecoder().decode(gunzip('kaopu-unified-human-workbench/assets/canonical.json.gz'))),rest=a.forward({phenotypes:c.referenceAnnyPhenotypes}),sourceBind=sourceWorld(m.evaluate().joints),binding=buildTargetBinding({sourceBind,jointNames:m.meta.joint_names,parents:m.d.parents,annyBoneNames:a.boneLabels,annyRestHeads:rest.boneHeads});fs.writeFileSync(new URL('skeleton-binding.json',import.meta.url),JSON.stringify({sourceBind,...binding}));console.log('Skeleton target bind exported');
